{"topic": "数据结构-AVL", "audience": "", "brief": {"objective": "学生能复述本页核心结论", "learningAction": "inspect", "requiredEvidence": "可见的核心结论", "keyClaim": "平衡因子：计算与判断（含平衡与失衡示例）", "misconception": "", "visualTask": "视觉直接编码本页核心关系", "evidencePolicy": "none"}, "scene": {"id": "balance-factor-def", "kind": "content", "headline": "平衡因子：计算与判断（含平衡与失衡示例）", "lead": "平衡因子 BF = 左子树高度 - 右子树高度。AVL 树要求每个节点的 BF 为 -1、0 或 1，超出则需旋转。", "notes": "先展示一个平衡树示例，再展示一个失衡树示例，让学生通过对比理解平衡因子的取值范围及失衡含义。", "blocks": [{"type": "sim", "engine": "widget", "html": "<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  .root { width: 100%; height: 100%; min-width: 0; min-height: 0; display: flex; flex-direction: column; background: var(--bg); color: var(--ink); font-family: var(--font-sans, system-ui, sans-serif); }
  .controls { display: flex; gap: 8px; padding: 8px 12px; flex-wrap: wrap; align-items: center; border-bottom: 1px solid var(--line); }
  .controls button { font-size: 12px; padding: 4px 12px; border-radius: 6px; border: 1px solid var(--line); background: var(--bg2); color: var(--ink); cursor: pointer; transition: background .15s, transform .15s; }
  .controls button:hover { background: var(--accent); color: var(--bg); }
  .controls button:active { transform: scale(.97); }
  .controls button.active { background: var(--accent); color: var(--bg); border-color: var(--accent); }
  .stage { flex: 1; display: flex; align-items: center; justify-content: center; padding: 8px; min-height: 0; }
  .stage svg { width: 100%; max-width: 600px; height: auto; display: block; }
  .readout { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 8px 12px; border-top: 1px solid var(--line); font-size: 12px; }
  .readout .left { color: var(--text2); }
  .readout .right { color: var(--ink); font-weight: 500; }
  .node-circle { cursor: pointer; transition: fill .15s; }
  .node-circle:hover { filter: brightness(1.2); }
  .node-text { pointer-events: none; user-select: none; }
  .label-height, .label-bf { pointer-events: none; user-select: none; font-size: 10px; }
</style>
<div class="root">
  <div class="controls">
    <button id="toggle-height" class="active">显示高度</button>
    <button id="toggle-bf" class="active">显示 BF</button>
  </div>
  <div class="stage">
    <svg viewBox="0 0 600 320" xmlns="http://www.w3.org/2000/svg">
      <g id="tree-lines"></g>
      <g id="tree-nodes"></g>
    </svg>
  </div>
  <div class="readout">
    <div class="left">BF 范围：-1, 0, 1</div>
    <div class="right" id="status-text">当前树：完全平衡，所有 BF=0</div>
  </div>
</div>
<script>
  (function() {
    // state_model
    const treeData = [
      {id:0, val:40, h:3, bf:0, left:1, right:2},
      {id:1, val:20, h:2, bf:0, left:3, right:4},
      {id:2, val:60, h:2, bf:0, left:5, right:6},
      {id:3, val:10, h:1, bf:0, left:-1, right:-1},
      {id:4, val:30, h:1, bf:0, left:-1, right:-1},
      {id:5, val:50, h:1, bf:0, left:-1, right:-1},
      {id:6, val:70, h:1, bf:0, left:-1, right:-1}
    ];
    let highlightNode = -1;
    let showHeight = true;
    let showBF = true;

    // layout constants
    const svgNS = 'http://www.w3.org/2000/svg';
    const svg = document.querySelector('.stage svg');
    const linesG = document.getElementById('tree-lines');
    const nodesG = document.getElementById('tree-nodes');
    const statusEl = document.getElementById('status-text');

    // compute positions for a complete binary tree of depth 3 (7 nodes)
    // root at (300, 40), level y spacing 80, x spacing halves each level
    function getNodePos(id) {
      const level = id === 0 ? 0 : (id <= 2 ? 1 : 2);
      const y = 40 + level * 80;
      let x;
      if (level === 0) x = 300;
      else if (level === 1) x = id === 1 ? 150 : 450;
      else {
        const parent = id <= 3 ? 1 : 2;
        const parentX = parent === 1 ? 150 : 450;
        const offset = 75;
        x = (id % 2 === 0) ? parentX + offset : parentX - offset;
      }
      return {x, y};
    }

    function getChildPos(parentId, childId) {
      if (childId === -1) return null;
      return getNodePos(childId);
    }

    // verification
    (function verify() {
      // all BF in {-1,0,1}
      treeData.forEach(n => { console.assert(n.bf >= -1 && n.bf <= 1, 'BF out of range'); });
      // root height = 3
      console.assert(treeData[0].h === 3, 'root height');
      // leaf height = 1
      [3,4,5,6].forEach(id => console.assert(treeData[id].h === 1, 'leaf height'));
      // each node height = 1 + max(child heights)
      function childHeight(id) { if (id === -1) return 0; return treeData.find(n => n.id === id).h; }
      treeData.forEach(n => {
        const expected = 1 + Math.max(childHeight(n.left), childHeight(n.right));
        console.assert(n.h === expected, `node ${n.id} height mismatch`);
      });
      // BF = left - right
      treeData.forEach(n => {
        const lh = childHeight(n.left);
        const rh = childHeight(n.right);
        console.assert(n.bf === lh - rh, `node ${n.id} BF mismatch`);
      });
    })();

    function update() {
      // clear
      linesG.innerHTML = '';
      nodesG.innerHTML = '';

      // draw lines
      treeData.forEach(n => {
        if (n.left !== -1) {
          const p = getNodePos(n.id);
          const c = getNodePos(n.left);
          const line = document.createElementNS(svgNS, 'line');
          line.setAttribute('x1', p.x);
          line.setAttribute('y1', p.y + 20);
          line.setAttribute('x2', c.x);
          line.setAttribute('y2', c.y - 20);
          line.setAttribute('stroke', 'var(--line)');
          line.setAttribute('stroke-width', '1.5');
          linesG.appendChild(line);
        }
        if (n.right !== -1) {
          const p = getNodePos(n.id);
          const c = getNodePos(n.right);
          const line = document.createElementNS(svgNS, 'line');
          line.setAttribute('x1', p.x);
          line.setAttribute('y1', p.y + 20);
          line.setAttribute('x2', c.x);
          line.setAttribute('y2', c.y - 20);
          line.setAttribute('stroke', 'var(--line)');
          line.setAttribute('stroke-width', '1.5');
          linesG.appendChild(line);
        }
      });

      // draw nodes
      treeData.forEach(n => {
        const pos = getNodePos(n.id);
        const g = document.createElementNS(svgNS, 'g');
        g.setAttribute('class', 'node-group');
        g.setAttribute('data-id', n.id);

        // outer circle
        const outer = document.createElementNS(svgNS, 'circle');
        outer.setAttribute('cx', pos.x);
        outer.setAttribute('cy', pos.y);
        outer.setAttribute('r', 20);
        outer.setAttribute('fill', 'var(--bg2)');
        outer.setAttribute('stroke', 'var(--line)');
        outer.setAttribute('stroke-width', '1.5');
        g.appendChild(outer);

        // inner circle (color by BF)
        const inner = document.createElementNS(svgNS, 'circle');
        inner.setAttribute('cx', pos.x);
        inner.setAttribute('cy', pos.y);
        inner.setAttribute('r', 14);
        inner.setAttribute('class', 'node-circle');
        // color: green for 0, yellow for ±1, red for out (none here)
        let fillColor;
        if (n.bf === 0) fillColor = 'var(--accent)';
        else if (Math.abs(n.bf) === 1) fillColor = 'var(--accent)';
        else fillColor = 'var(--accent)';
        if (highlightNode === n.id) fillColor = 'var(--accent)';
        inner.setAttribute('fill', fillColor);
        inner.setAttribute('stroke', 'none');
        g.appendChild(inner);

        // value text
        const valText = document.createElementNS(svgNS, 'text');
        valText.setAttribute('x', pos.x);
        valText.setAttribute('y', pos.y + 4);
        valText.setAttribute('text-anchor', 'middle');
        valText.setAttribute('class', 'node-text');
        valText.setAttribute('fill', 'var(--ink)');
        valText.setAttribute('font-size', '12');
        valText.setAttribute('font-weight', '600');
        valText.textContent = n.val;
        g.appendChild(valText);

        // height label (above)
        const hText = document.createElementNS(svgNS, 'text');
        hText.setAttribute('x', pos.x);
        hText.setAttribute('y', pos.y - 26);
        hText.setAttribute('text-anchor', 'middle');
        hText.setAttribute('class', 'label-height');
        hText.setAttribute('fill', 'var(--text2)');
        hText.setAttribute('font-size', '10');
        hText.textContent = showHeight ? `h=${n.h}` : '';
        g.appendChild(hText);

        // BF label (below)
        const bfText = document.createElementNS(svgNS, 'text');
        bfText.setAttribute('x', pos.x);
        bfText.setAttribute('y', pos.y + 34);
        bfText.setAttribute('text-anchor', 'middle');
        bfText.setAttribute('class', 'label-bf');
        bfText.setAttribute('fill', 'var(--text2)');
        bfText.setAttribute('font-size', '10');
        bfText.textContent = showBF ? `BF=${n.bf}` : '';
        g.appendChild(bfText);

        // click handler
        inner.addEventListener('click', function(e) {
          e.stopPropagation();
          const id = parseInt(g.dataset.id);
          if (highlightNode === id) {
            highlightNode = -1;
            statusEl.textContent = '当前树：完全平衡，所有 BF=0';
          } else {
            highlightNode = id;
            const node = treeData.find(n => n.id === id);
            let detail = `值:${node.val}, 高度:${node.h}, BF:${node.bf}`;
            if (node.left !== -1 || node.right !== -1) {
              const leftVal = node.left !== -1 ? treeData.find(n => n.id === node.left).val : '无';
              const rightVal = node.right !== -1 ? treeData.find(n => n.id === node.right).val : '无';
              detail += `, 左子:${leftVal}, 右子:${rightVal}`;
            } else {
              detail += ', 无子节点';
            }
            statusEl.textContent = detail;
          }
          update();
        });

        nodesG.appendChild(g);
      });

      // click on blank area to reset
      svg.addEventListener('click', function(e) {
        if (e.target === svg || e.target === linesG || e.target === nodesG) {
          highlightNode = -1;
          statusEl.textContent = '当前树：完全平衡，所有 BF=0';
          update();
        }
      });
    }

    // toggle buttons
    document.getElementById('toggle-height').addEventListener('click', function() {
      showHeight = !showHeight;
      this.classList.toggle('active');
      update();
    });
